window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7e917f1ad56143ef"]={"versions": [{"id": "FIG-7e917f1ad56143ef", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Prozessdiagramm (Workflow- und Tool-Interaktionsmodell) aus dem AUTOSAR-Dokument TR Interoperability of AUTOSAR Tools (Kapitel 3, Figure 3.2). Das Diagramm beschreibt das fundamentale Architekturkonzept zur Handhabung von AUTOSAR-Modellen, die physisch über mehrere XML-Dateifragmente verteilt sind. Es verdeutlicht die Entkopplung zwischen der dateibasierten Persistenzschicht (AUTOSAR XML / ARXML) und der werkzeuginternen, integrierten Modellrepräsentation im Authoring Tool.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Komponenten / Werkzeuge:\n<ul class=\"fig-list\"><li><code>Authoring Tool</code>: Ausführende AUTOSAR-Autorenumgebung, dargestellt als übergeordnete Prozessdomäne, welche die Bearbeitungsschritte steuert (assoziativ verknüpft über gestrichelte Linien).\n</li></ul>\n</li><li>Aktivitäten / Prozessschritte:\n<ul class=\"fig-list\"><li><code>Merge Description</code>: Import- und Fusionsschritt zur Konsolidierung partizipierender Dateifragmente.\n</li><li><code>edit model</code>: Modifikationsphase auf dem internalisierten Gesamtsystemmodell.\n</li><li><code>Produce XML description / Spit to Fragments</code>: Serialisierungs- und Partitionierungsschritt zur Neugenerierung von ARXML-Dateifragmenten.\n</li></ul>\n</li><li>Datenentitäten &amp; Artefakte:\n<ul class=\"fig-list\"><li><code>Original System Description Fragment 1 :System</code> bis <code>Original System Description Fragment n :System</code>: Eingangs-ARXML-Dateifragmente (Instanzen des Metamodell-Wurzelelements <code>System</code>).\n</li><li><code>Original Model : System</code>: Vollständige, intern im Werkzeug zusammengeführte Datenstruktur des Gesamtsystems vor der Bearbeitung.\n</li><li><code>Modified Model :System</code>: Konsolidierte interne Datenstruktur des Gesamtsystems nach erfolgter Bearbeitung.\n</li><li><code>Modified System Description Fragment a :System</code> bis <code>Modified System Description Fragment x :System</code>: Neu erzeugte, partitionierte ARXML-Ausgabedateifragmente.\n</li></ul>\n</li><li>Schnittstellen:\n<ul class=\"fig-list\"><li>Externe XML-Dateischnittstelle (persistenter I/O über das Dateisystem).\n</li><li>Interne Schnittstelle zwischen Parser/Merger, Bearbeitungskern und Serializer zur In-Memory-Modellmanipulation.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Fragment-Erfassung &amp; Modell-Merge: Mehrere unabhängige Eingangs-XML-Dateien (<code>Fragment 1</code> bis <code>n</code>) werden vom Authoring Tool eingelesen. Im Schritt <code>Merge Description</code> werden die darin enthaltenen Teilmodelle semantisch (auf Metamodellebene, nicht als reines Text-Diff) zu einem einheitlichen In-Memory-Zustand fusioniert.\n</li><li>Konsolidierte Repräsentation: Als Resultat des Merges entsteht die interne, referentiell geschlossene Datenstruktur <code>Original Model : System</code>.\n</li><li>Modellbearbeitung: Innerhalb der Werkzeugumgebung führt der Schritt <code>edit model</code> interaktive oder regelbasierte Änderungen an den Modellelementen durch und überführt das Modell in den Zustand <code>Modified Model :System</code>.\n</li><li>Serialisierung &amp; Re-Fragmentierung: Der Schritt <code>Produce XML description / Spit to Fragments</code> validiert das geänderte Gesamtmodell und serialisiert es erneut in mehrere physische XML-Fragmente (<code>Fragment a</code> bis <code>x</code>), wobei die Partitionierung anhand der Splitting-Regeln des Generic Structure Template (GST) erfolgt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Relevanz: Verbindliche Vorgabe für die Architektur von AUTOSAR-kompatiblen Autorentools zur Gewährleistung der Werkzeuginteroperabilität bei Multi-File-Modellen.\n</li><li>Model-Level Merge: Der Merge-Prozess darf keinesfalls auf XML-Textebene ausgeführt werden; er muss auf Ebene der durch ARXML repräsentierten partiellen AUTOSAR-Metamodelle erfolgen.\n</li><li>Konfliktmanagement: Tools müssen Mechanismen zur manuellen oder regelbasierten Behebung von Merge-Konflikten (z. B. widersprüchliche Attributwerte oder parallele Modifikationen identischer UUIDs/Short-Names) implementieren.\n</li><li>Fragmentierungsregeln: Die Aufteilung in Ausgabedateien unterliegt den im AUTOSAR Generic Structure Template festgelegten Granularitäten (Stereotyp «atpSplitable»). Referenzen über Fragmentgrenzen hinweg müssen syntaktisch und semantisch valide bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6c798d1b0bc3e5eb", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Datenfluss- und Prozessdiagramm (Workflow- und Tool-Interaktionsmodell) aus dem AUTOSAR-Dokument TR Interoperability of AUTOSAR Tools (Kapitel 3, Figure 3.2). Das Diagramm beschreibt das fundamentale Architekturkonzept zur Handhabung von AUTOSAR-Modellen, die physisch über mehrere XML-Dateifragmente verteilt sind. Es verdeutlicht die Entkopplung zwischen der dateibasierten Persistenzschicht (AUTOSAR XML / ARXML) und der werkzeuginternen, integrierten Modellrepräsentation im Authoring Tool.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Komponenten / Werkzeuge:\n<ul class=\"fig-list\"><li><code>Authoring Tool</code>: Ausführende AUTOSAR-Autorenumgebung, dargestellt als übergeordnete Prozessdomäne, welche die Bearbeitungsschritte steuert (assoziativ verknüpft über gestrichelte Linien).\n</li></ul>\n</li><li>Aktivitäten / Prozessschritte:\n<ul class=\"fig-list\"><li><code>Merge Description</code>: Import- und Fusionsschritt zur Konsolidierung partizipierender Dateifragmente.\n</li><li><code>edit model</code>: Modifikationsphase auf dem internalisierten Gesamtsystemmodell.\n</li><li><code>Produce XML description / Spit to Fragments</code>: Serialisierungs- und Partitionierungsschritt zur Neugenerierung von ARXML-Dateifragmenten.\n</li></ul>\n</li><li>Datenentitäten &amp; Artefakte:\n<ul class=\"fig-list\"><li><code>Original System Description Fragment 1 :System</code> bis <code>Original System Description Fragment n :System</code>: Eingangs-ARXML-Dateifragmente (Instanzen des Metamodell-Wurzelelements <code>System</code>).\n</li><li><code>Original Model : System</code>: Vollständige, intern im Werkzeug zusammengeführte Datenstruktur des Gesamtsystems vor der Bearbeitung.\n</li><li><code>Modified Model :System</code>: Konsolidierte interne Datenstruktur des Gesamtsystems nach erfolgter Bearbeitung.\n</li><li><code>Modified System Description Fragment a :System</code> bis <code>Modified System Description Fragment x :System</code>: Neu erzeugte, partitionierte ARXML-Ausgabedateifragmente.\n</li></ul>\n</li><li>Schnittstellen:\n<ul class=\"fig-list\"><li>Externe XML-Dateischnittstelle (persistenter I/O über das Dateisystem).\n</li><li>Interne Schnittstelle zwischen Parser/Merger, Bearbeitungskern und Serializer zur In-Memory-Modellmanipulation.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Fragment-Erfassung &amp; Modell-Merge: Mehrere unabhängige Eingangs-XML-Dateien (<code>Fragment 1</code> bis <code>n</code>) werden vom Authoring Tool eingelesen. Im Schritt <code>Merge Description</code> werden die darin enthaltenen Teilmodelle semantisch (auf Metamodellebene, nicht als reines Text-Diff) zu einem einheitlichen In-Memory-Zustand fusioniert.\n</li><li>Konsolidierte Repräsentation: Als Resultat des Merges entsteht die interne, referentiell geschlossene Datenstruktur <code>Original Model : System</code>.\n</li><li>Modellbearbeitung: Innerhalb der Werkzeugumgebung führt der Schritt <code>edit model</code> interaktive oder regelbasierte Änderungen an den Modellelementen durch und überführt das Modell in den Zustand <code>Modified Model :System</code>.\n</li><li>Serialisierung &amp; Re-Fragmentierung: Der Schritt <code>Produce XML description / Spit to Fragments</code> validiert das geänderte Gesamtmodell und serialisiert es erneut in mehrere physische XML-Fragmente (<code>Fragment a</code> bis <code>x</code>), wobei die Partitionierung anhand der Splitting-Regeln des Generic Structure Template (GST) erfolgt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Relevanz: Verbindliche Vorgabe für die Architektur von AUTOSAR-kompatiblen Autorentools zur Gewährleistung der Werkzeuginteroperabilität bei Multi-File-Modellen.\n</li><li>Model-Level Merge: Der Merge-Prozess darf keinesfalls auf XML-Textebene ausgeführt werden; er muss auf Ebene der durch ARXML repräsentierten partiellen AUTOSAR-Metamodelle erfolgen.\n</li><li>Konfliktmanagement: Tools müssen Mechanismen zur manuellen oder regelbasierten Behebung von Merge-Konflikten (z. B. widersprüchliche Attributwerte oder parallele Modifikationen identischer UUIDs/Short-Names) implementieren.\n</li><li>Fragmentierungsregeln: Die Aufteilung in Ausgabedateien unterliegt den im AUTOSAR Generic Structure Template festgelegten Granularitäten (Stereotyp «atpSplitable»). Referenzen über Fragmentgrenzen hinweg müssen syntaktisch und semantisch valide bleiben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7e917f1ad56143ef", "to": "FIG-6c798d1b0bc3e5eb", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Aktivitäten <code>Merge Description</code>, <code>edit model</code> und <code>Produce XML description / Spit to Fragments</code>: Symbolform von abgerundeten Rechtecken (wobei <code>Merge Description</code> rosa hinterlegt war) auf einheitliche gelbe Prozess-Chevrons (Blockpfeile) umgestellt.\n</li><li>Beschriftungen: Typografische Vereinheitlichung der Abstände vor den Doppelpunkten bei den Instanzbezeichnern (<code>Original System Description Fragment 1: System</code>, <code>Original System Description Fragment n: System</code>, <code>Original Model: System</code>, <code>Modified Model: System</code>).\n</li></ul>"}]};
